head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.getDateCurrent = function(type) {
	var today = new Date();
	var dd = 0;
	var isFirstDay = false;
	if (type == 0) {
		//current date
		dd = today.getDate();
	} else if (type == 1) {
		//next date
		dd = today.getDate() + 1;
	} else {
		//previous date
		if (today.getDate() === 1) {
			isFirstDay = true;
			var date = new Date();
			date.setHours(-1);
			dd = date.getDate();
		} else {
			dd = today.getDate() - 1;
		}
	}
	var mm = isFirstDay ? today.getMonth() : today.getMonth() + 1;
	var yyyy = today.getFullYear();
	if (dd < 10) {
		dd = '0' + dd
	}
	if (mm < 10) {
		mm = '0' + mm
	}
	today = yyyy + "-" + mm + "-" + dd;
	return today;
};
scwin.__ispreviousElement = function() {
	var id = $('td.w2calendar_selected').last().attr("id");
	var el = scwin.__getDom($p.id + id).previousSibling;
	return el;
};
scwin.__isnextElement = function() {
	var id = $('td.w2calendar_selected').last().attr("id");
	var el = scwin.__getDom($p.id + id).nextSibling;
	return el;
};
scwin.checkVal1 = function() {
	return scwin.getDateCurrent(0) === scwin.__getObj('inputCalendar1_calendar_currentDate').innerText;
};
scwin.checkVal2 = function() {
	return scwin.getDateCurrent(1) === scwin.__getObj('inputCalendar1_calendar_currentDate').innerText;
};
scwin.checkVal3 = function() {
	return scwin.getDateCurrent(0) === scwin.__getObj('inputCalendar2_calendar_currentDate').innerText;
};
scwin.checkVal4 = function() {
	return scwin.getDateCurrent(2) === scwin.__getObj('inputCalendar2_calendar_currentDate').innerText;
};
